// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 10 ether);
        address caller = c.smartfix_owner();
        vm.deal(address(c), amount);
        vm.deal(caller, 0);
        uint256 callerBalBefore = caller.balance;
        uint256 contractBalBefore = address(c).balance;

        vm.prank(caller);
        c.sudicideAnyone();

        uint256 callerBalAfter = caller.balance;
        // After selfdestruct, contract is gone, balance is 0
        // In reference C, caller receives contract balance; in buggy M, caller does not.
        assertTrue(callerBalAfter == callerBalBefore + contractBalBefore);
    }
}

